insert into public.curriculum_competencies (id, course_id, academic_level, competency_area_id, statement, status) values
  ('grad-aut501-integrated-systems','aut-501','graduate',null,'Analyze interactions among advanced automotive system domains, identify interface evidence and uncertainty, and design a traceable system-level verification strategy.','planned'),
  ('grad-aut515-systems-modeling','aut-515','graduate',null,'Construct and evaluate automotive system models, justify parameter choices and assumptions, and assess model validity against appropriate evidence.','planned'),
  ('grad-aut520-data-analytics','aut-520','graduate',null,'Evaluate vehicle datasets using appropriate analytical methods, distinguish statistical patterns from supported technical conclusions, and document uncertainty and validation needs.','planned'),
  ('grad-aut530-advanced-ev-systems','aut-530','graduate',null,'Analyze advanced EV subsystem interactions, evaluate operating evidence across energy-conversion domains, and design a source-supported verification strategy.','planned'),
  ('grad-aut535-battery-systems','aut-535','graduate',null,'Evaluate battery-system models and diagnostic evidence, distinguish estimated states from measured observations, and justify a validation strategy that respects safety and source boundaries.','planned'),
  ('grad-aut540-power-electronics','aut-540','graduate',null,'Analyze vehicle power-electronic energy conversion and control relationships, interpret evidence across electrical and thermal domains, and identify applicable source requirements for validation.','planned'),
  ('grad-aut545-energy-management','aut-545','graduate',null,'Evaluate vehicle energy-flow strategies, articulate optimization objectives and constraints, and justify conclusions using traceable operating evidence.','planned'),
  ('grad-aut550-automotive-networks','aut-550','graduate',null,'Analyze advanced vehicle-network behavior and topology evidence, distinguish communication symptoms from root-cause conclusions, and design a traceable network verification strategy.','planned'),
  ('grad-aut555-embedded-ecu','aut-555','graduate',null,'Evaluate embedded automotive architecture and software/hardware interactions, identify interface evidence and timing constraints conceptually, and design an applicable validation approach.','planned'),
  ('grad-aut560-adas-perception','aut-560','graduate',null,'Evaluate multi-sensor perception evidence, explain sensor-fusion and calibration dependencies, and design a validation strategy that documents environment and configuration limitations.','planned'),
  ('grad-aut565-autonomous-systems','aut-565','graduate',null,'Analyze autonomous-system functional chains, identify cross-domain dependencies and failure evidence, and design a traceable simulation or test validation strategy.','planned'),
  ('grad-aut570-cybersecurity','aut-570','graduate',null,'Evaluate automotive cybersecurity risks and controls using threat-model evidence, distinguish defensive verification from exploit development, and document residual risk and validation needs.','planned'),
  ('grad-aut575-software-defined-vehicle','aut-575','graduate',null,'Evaluate software-defined vehicle architecture tradeoffs, trace software/data dependencies, and design a configuration-aware verification and lifecycle strategy.','planned'),
  ('grad-aut580-control-systems','aut-580','graduate',null,'Evaluate advanced automotive control-system models and evidence, assess stability and estimation assumptions, and justify a validation strategy against system requirements.','planned'),
  ('grad-aut585-digital-twins','aut-585','graduate',null,'Evaluate a vehicle digital-twin architecture, distinguish model state from observed vehicle state, and design calibration and validation activities using traceable data.','planned'),
  ('grad-aut590-technology-seminar','aut-590','graduate',null,'Critically synthesize current automotive research and technical publications, compare competing claims, and communicate evidence-supported conclusions with explicit uncertainty and source provenance.','planned')
